mapper.select:
SELECT r.`id` AS `id`, r.`item_id` AS `itemId`, r.`shop_id` AS `shopId`, r.`user_email` AS `userEmail`, r.`reservation_id` AS `reservationId`, r.`content` AS `content`, r.`rating` AS `rating`, r.`useful_count` AS `usefulCount`, r.`created_at` AS `createdAt`, r.`updated_at` AS `updatedAt`, u.`name` AS `userName`, /* [FBI 정규화] 해당 유저가 이 아이템에 대해 결제한 날짜 중 가장 최신 날짜를 매칭 */ (SELECT MAX(o.`created_at`) FROM `cors`.`orders` AS o WHERE o.`user_email` = r.`user_email`) AS `orderDate` FROM `cors`.`item_reviews` AS r LEFT JOIN `cors`.`users` AS u ON r.`user_email` = u.`email` WHERE r.`item_id` = #{itemId}
ORDER BY r.`useful_count` DESC, r.`created_at` DESC
ORDER BY r.`created_at` DESC

/* 1. 예약 고객: 방문완료 후 60일 이내인 건만 허용 */
(
    SELECT ri.`id`
    FROM `cors`.`reservation_items` AS ri
             INNER JOIN `cors`.`reservations` AS res ON ri.`reservation_id` = res.`id`
    WHERE res.`user_email` = #{email}
      AND ri.`item_id` = #{itemId}
      AND (TRIM(res.`status`) = '확정' OR TRIM(res.`status`) = '완료')
        /* [보안 추가] 방문일로부터 60일 이내 데이터만 조회 */
      AND res.`visit_date` >= DATE_SUB(NOW(), INTERVAL 60 DAY)
      AND ri.`id` NOT IN (SELECT IFNULL(`reservation_id`, 0) FROM `cors`.`item_reviews`)
    ORDER BY ri.`id` DESC
    LIMIT 1
)
UNION ALL
/* 2. 일반 구매 고객: 구매확정 후 60일 이내인 건만 허용 */
(
    SELECT oi.`id`
    FROM `cors`.`order_items` AS oi
             INNER JOIN `cors`.`orders` AS o ON oi.`order_id` = o.`id`
    WHERE o.`user_email` = #{email}
      AND oi.`item_id` = #{itemId}
      AND oi.`status` = 4
        /* [보안 추가] 주문(결제)일로부터 60일 이내 데이터만 조회 */
      AND o.`created_at` >= DATE_SUB(NOW(), INTERVAL 60 DAY)
      AND oi.`id` NOT IN (SELECT IFNULL(`reservation_id`, 0) FROM `cors`.`item_reviews`)
    LIMIT 1
)
LIMIT 1
